<template>
  <section class="narriva-compliance" aria-label="Narriva Clinical Compliance Check" :aria-busy="busy">
    <header><div><img :src="NARRIVA_BRAND.compliance" alt="Narriva Compliance by AuricWell" /><h2>Narriva Clinical Compliance Check <span>5 checks</span></h2></div><img class="narriva-compliance__shield" :src="verified ? NARRIVA_BRAND.verified : NARRIVA_BRAND.notVerified" :alt="verified ? 'Narriva checks passed' : 'Not verified'" /></header>
    <p v-if="error" class="narriva-compliance__error" role="alert">{{ error }}</p>
    <p v-if="!review && !busy" class="narriva-compliance__hint">Generate your note to check its documentation. A check is confirmed only after Narriva returns its result.</p>
    <p v-if="review?.status === 'stale'" class="narriva-compliance__error">The note changed. Run the checks again before Quick Sign.</p>
    <ol>
      <li v-for="(check, index) in checks" :key="check.id" :class="`narriva-check--${check.status}`">
        <div class="narriva-check__title"><span class="narriva-check__state" :class="{ spinning: check.status === 'running' }" aria-hidden="true">{{ symbol(check.status) }}</span><strong>{{ index + 1 }}. {{ check.label }}</strong><span>{{ label(check.status) }}</span></div>
        <ul v-if="check.findings?.length" class="narriva-check__findings"><li v-for="finding in check.findings" :key="finding.id">
          <p>{{ finding.message }}</p>
          <p v-if="finding.bypassed || finding.status === 'bypassed'" class="narriva-check__bypass-record">Kept as written. {{ finding.bypassReason || finding.reason || '' }} Quick Sign is unavailable.</p>
          <template v-else>
            <button v-if="finding.action && finding.action !== 'none'" type="button" :disabled="busy || readOnly" @click="$emit('action', { checkId: check.id, finding })">{{ actionLabel(finding.action) }}</button>
            <button v-if="finding.canBypass && !readOnly" type="button" :disabled="busy" @click="openBypass = openBypass === finding.id ? '' : finding.id">Keep my note as it is</button>
            <form v-if="openBypass === finding.id && finding.canBypass && !readOnly" @submit.prevent="bypass(finding)"><label>Reason for keeping this note<textarea v-model="reasons[finding.id]" rows="2" minlength="5" maxlength="2000" required :disabled="busy" /></label><small>This records your decision and removes Quick Sign eligibility.</small><button type="submit" :disabled="busy || (reasons[finding.id]?.trim().length || 0) < 5">Record decision</button></form>
          </template>
        </li></ul>
        <slot v-if="check.id === 'risk_safety'" name="risk" :required="riskAssessmentRequired || review?.riskAssessmentRequired === true" />
      </li>
    </ol>
    <footer><span v-if="review?.quickSignEligible === true && verified" class="narriva-compliance__eligible"><img :src="NARRIVA_BRAND.quickSign" alt="Narriva Quick Sign Approved" /></span><span v-else-if="review?.status === 'bypassed'">Review decisions saved. Use the standard signature review.</span><span v-else-if="verified">Documentation checks passed.</span><span v-else>{{ busy ? 'Checking the current note…' : 'Review and resolve any findings before signing.' }}</span><button v-if="review || error" type="button" :disabled="busy || readOnly" @click="$emit('retry')">{{ busy ? 'Checking…' : 'Run checks again' }}</button></footer>
  </section>
</template>
<script setup>
import { computed, reactive, ref } from 'vue';
import { NARRIVA_BRAND, NARRIVA_CHECKS } from '../../config/narrivaBrand.js';
const props = defineProps({ review: { type: Object, default: null }, busy: Boolean, error: { type: String, default: '' }, readOnly: Boolean, riskAssessmentRequired:Boolean });
const emit = defineEmits(['retry', 'resolve', 'action']);
const reasons = reactive({}), openBypass = ref('');
const checks = computed(() => NARRIVA_CHECKS.map((item, index) => ({ ...item, ...(props.review?.checks || []).find(check => check.id === item.id), label: item.label, status: (props.review?.checks || []).find(check => check.id === item.id)?.status || (props.busy && !props.review && index === 0 ? 'running' : 'pending') })));
const verified = computed(() => props.review?.status === 'passed' && checks.value.every(check => check.status === 'passed'));
const label = value => ({ pending: 'Waiting', running: 'Checking', passed: 'Confirmed', action_required: 'Review needed', bypassed: 'Kept as written', unavailable: 'Unavailable', failed: 'Unavailable', stale: 'Changed' }[value] || 'Waiting');
const symbol = value => ({ passed: '✓', running: '◌', action_required: '!', bypassed: '–', unavailable: '!', failed: '!' }[value] || '○');
const actionLabel = action => ({ assessment:'Add assessment or attachment',encounter:'Review encounter details',clinical_context:'Review clinical context',edit_note:'Edit note content',risk_assessment: 'Open risk assessment', add_risk_assessment: 'Open risk assessment', service_code: 'Review service code', change_service_code: 'Review service code', participants: 'Review participants', review_participants: 'Review participants', consent: 'Review consent', add_assessment: 'Add assessment or attachment', treatment_plan: 'Review treatment plan', narrative: 'Edit Session Narrative' }[typeof action === 'string' ? action : action?.id] || action?.label || 'Review this finding');
function bypass(finding) { const reason = reasons[finding.id]?.trim(); if (!reason || reason.length < 5 || !finding.canBypass || props.busy) return; emit('resolve', { findingId: finding.id, action: 'bypass', reason }); openBypass.value = ''; }
</script>
<style scoped>
.narriva-compliance{background:#fff;border:1px solid #d6e1ec;border-radius:15px;padding:20px;margin:18px 0;color:#173754}.narriva-compliance>header{display:flex;justify-content:space-between;align-items:center;gap:16px}.narriva-compliance header>div>img{width:260px;max-width:100%;height:auto}.narriva-compliance h2{font-size:17px;margin:8px 0 12px}.narriva-compliance h2 span{font-size:12px;font-weight:400;color:#687d90;margin-left:8px}.narriva-compliance__shield{width:55px;height:55px;object-fit:contain}.narriva-compliance ol{list-style:none;padding:0;margin:0}.narriva-compliance ol>li{border-top:1px solid #e3eaf1;padding:13px 0}.narriva-check__title{display:flex;align-items:center;gap:10px}.narriva-check__title>strong{flex:1;font-size:14px}.narriva-check__title>span:last-child{font-size:11px;color:#657b8e;text-align:right}.narriva-check__state{display:grid;place-items:center;width:25px;height:25px;border:1px solid #c9d6e2;color:#71889b;border-radius:50%;font-size:18px;flex:none}.narriva-check--passed .narriva-check__state{background:#e7f6ef;border-color:#b6deca;color:#26724e}.narriva-check--action_required .narriva-check__state,.narriva-check--unavailable .narriva-check__state{color:#9c651a;border-color:#e2c593;background:#fff7e8}.narriva-check__findings{list-style:none;margin:8px 0 0 35px;padding:0;font-size:13px;line-height:1.5}.narriva-check__findings p{margin:6px 0}.narriva-check__findings button,.narriva-compliance footer>button{font:inherit;font-size:12px;border:1px solid #cbd9e5;border-radius:7px;background:#f8fbfe;padding:7px 9px;color:#205782;margin:3px 7px 3px 0;cursor:pointer}.narriva-check__findings button:disabled,.narriva-compliance footer>button:disabled{opacity:.5;cursor:default}.narriva-check__findings form{background:#f7f9fc;padding:10px;margin:8px 0;border-radius:8px}.narriva-check__findings label{display:block}.narriva-check__findings textarea{display:block;box-sizing:border-box;width:100%;font:inherit;border:1px solid #c5d4e2;border-radius:6px;margin:5px 0;padding:8px}.narriva-check__findings small{display:block;color:#7b6b4c}.narriva-compliance footer{display:flex;align-items:center;justify-content:space-between;border-top:1px solid #e3eaf1;padding-top:12px;gap:10px;font-size:12px;color:#62778b}.narriva-compliance__eligible img{width:245px;max-width:100%;height:auto}.narriva-compliance__error{color:#a12c29;font-size:13px}.narriva-compliance__hint{font-size:13px;color:#647c90}.spinning{animation:narriva-spin 1s linear infinite}@keyframes narriva-spin{to{transform:rotate(360deg)}}@media(prefers-reduced-motion:reduce){.spinning{animation:none}}@media(max-width:600px){.narriva-compliance{padding:14px}.narriva-check__title{gap:7px}.narriva-check__title>strong{font-size:13px}.narriva-compliance header>div>img{width:220px}.narriva-compliance footer{align-items:flex-start}.narriva-check__findings{margin-left:0}}
</style>
